const base='/api/lounge/v2/stage-bridge';
export const consoleStyle=`:root{color-scheme:dark}*{box-sizing:border-box}body{background:var(--void);color:var(--text-high);font:16px system-ui;margin:32px;max-width:1100px}a{color:var(--cyan)}button,select{font:inherit;max-width:100%;min-height:44px;padding:12px;margin:8px;border:1px solid var(--text-faint);border-radius:6px}button:focus-visible,select:focus-visible,a:focus-visible{outline:2px solid var(--cyan);outline-offset:2px}article,#recovery{border:1px solid var(--text-faint);margin:24px 0;padding:24px;border-radius:16px}img{max-width:100%;max-height:450px;display:block;background:var(--panel)}p{line-height:1.5;overflow-wrap:anywhere}button:disabled{opacity:.5}[hidden]{display:none}@media(max-width:520px){body{margin:20px 16px}article,#recovery{padding:18px}button,select{margin:6px 0}}`;
export function consoleHtml(csrf,{curatedEnabled=false,ownerKey,sessionKey}={}){
 if(typeof csrf!=='string'||!/^[A-Za-z0-9_-]{16,128}$/.test(csrf)||typeof ownerKey!=='string'||!/^[a-f0-9]{64}$/.test(ownerKey)||typeof sessionKey!=='string'||!/^[a-f0-9]{64}$/.test(sessionKey))throw Error('Invalid review console context');
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf" content="${csrf}"><meta name="review-owner" content="${ownerKey}"><meta name="review-session" content="${sessionKey}"><title>CUHZ Lounge — Artwork review</title><link rel="stylesheet" href="/api/lounge/v2/stage/tokens.css"><link rel="stylesheet" href="${base}/console.css"></head><body><main><h1>Artwork review</h1><p>Only artwork deliberately submitted for review appears here. Approval makes an item eligible for the stage. Keep the stage held through approval until you are ready for an attended reveal.</p><p><a href="/api/lounge/v2/stage/ops">Stage controls</a> · <a href="/api/lounge/v2/stage/ops/emergency">Emergency hold</a> · <a href="/auth?next=%2Fapi%2Flounge%2Fv2%2Fstage-bridge%2Fops">Sign in again</a></p>${curatedEnabled===true?'<p><a href="/api/lounge/v2/stage-bridge/curated/ops">Prepare owner artwork</a></p>':''}<button id="refresh" type="button">Refresh queue</button><button id="stop" type="button">Stop and clear previews</button><p id="status" role="status" aria-live="polite" tabindex="-1">Checking the current owner session…</p><section id="recovery" hidden aria-labelledby="recovery-heading"><h2 id="recovery-heading">Resolve the pending decision</h2><p>Its outcome may be unknown. No new decision can start. Recovery deliberately uses the original receipt and exact request.</p><p id="recovery-summary"></p><p>Receipt: <span id="receipt"></span></p><button id="recover" type="button" disabled>Recover the same decision</button></section><section id="queue" aria-label="Submitted artwork"></section></main><script src="${base}/console.js" defer></script></body></html>`;
}
export const consoleScript=String.raw`'use strict';
const commandTerminal={COMMAND_RETIRED:'This older request has expired. Refresh the current private status before starting a new operation. Your saved artwork is retained.',COMMAND_CAPACITY_REVIEW_REQUIRED:'Stage controls need owner review. Public output is held; no new action was recorded. Your saved artwork is retained.'};
const base='/api/lounge/v2/stage-bridge',q=id=>document.querySelector('#'+id),queue=q('queue'),status=q('status');
const csrf=document.querySelector('meta[name=csrf]').content,ownerKey=document.querySelector('meta[name=review-owner]').content,sessionKey=document.querySelector('meta[name=review-session]').content;
const storageKey='cuhz-review-decision-pending-v1',hash=/^[a-f0-9]{64}$/,uuid=/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i;
const reasons=['content_reviewed','content_policy','rights_unclear','quality_issue'],controllers=new Set(),cards=new Map();
let pending=null,current=null,busy=false,locked=false,epoch=0,renderEpoch=0;
const active=run=>!locked&&run===epoch,clean=(value,max)=>typeof value==='string'&&value.trim().length>0&&value.length<=max&&!/[\x00-\x1f\x7f]/.test(value);
const exact=(value,names)=>value&&typeof value==='object'&&!Array.isArray(value)&&Object.keys(value).sort().join(',')===names.sort().join(',');
const itemKey=item=>item?[item.id,item.itemId,item.title,item.displayName,item.label,item.imageUrl].join('\n'):'';
const listKey=data=>data.reviews.map(itemKey).join('\n\n');
const node=(tag,text)=>{const element=document.createElement(tag);if(text)element.textContent=text;return element;};
function allow(){const ready=!locked&&!busy&&!!current;q('refresh').disabled=locked||busy;q('stop').disabled=locked;q('recovery').hidden=!pending||!current;q('receipt').textContent=pending&&current?pending.payload.requestId:'';q('recovery-summary').textContent=pending&&current?'Saved decision: '+pending.payload.decision+' · '+pending.payload.reason.replaceAll('_',' ')+' · Review '+pending.payload.reviewId:'';q('recover').disabled=!(ready&&pending);for(const card of cards.values()){card.select.disabled=!ready||!!pending;for(const button of card.buttons)button.disabled=!ready||!!pending||(button.dataset.decision==='approved'&&!card.loaded);}}
function invalidate(message){if(locked)return;locked=true;epoch++;renderEpoch++;for(const controller of controllers)controller.abort();controllers.clear();current=null;pending=null;cards.clear();queue.replaceChildren();status.textContent=message;allow();}
function saved(value){return exact(value,['ownerKey','sessionKey','payload'])&&value.ownerKey===ownerKey&&hash.test(value.sessionKey)&&exact(value.payload,['requestId','reviewId','decision','reason'])&&uuid.test(value.payload.requestId)&&uuid.test(value.payload.reviewId)&&['approved','rejected'].includes(value.payload.decision)&&reasons.includes(value.payload.reason);}
function persist(value){const raw=JSON.stringify(value);sessionStorage.setItem(storageKey,raw);if(sessionStorage.getItem(storageKey)!==raw)throw Error('STORAGE');pending=value;}
function forget(){try{sessionStorage.removeItem(storageKey);if(sessionStorage.getItem(storageKey)!==null)throw Error();}catch{throw Error('STORAGE');}pending=null;}
async function request(path,options,run){const controller=new AbortController();controllers.add(controller);let timer;try{return await Promise.race([(async()=>{const response=await fetch(base+path,{credentials:'same-origin',cache:'no-store',redirect:'error',referrerPolicy:'no-referrer',...options,signal:controller.signal});if(!active(run)||controller.signal.aborted)throw Error('CANCELLED');if(response.status===401||response.status===403)throw Error('SESSION_CHANGED');const data=await response.json();if(!active(run)||controller.signal.aborted)throw Error('CANCELLED');if(!response.ok||data?.ok===false){const terminal=data?.code||data?.error;if(response.status===409&&Object.hasOwn(commandTerminal,terminal))throw Error(terminal);if(response.status>=500||data?.error==='BRIDGE_OUTCOME_UNKNOWN')throw Error('UNAVAILABLE');throw Error('REFUSED');}return data;})(),new Promise((_,reject)=>{timer=setTimeout(()=>{controller.abort();reject(Error('UNAVAILABLE'));},8000);})]);}finally{clearTimeout(timer);controller.abort();controllers.delete(controller);}}
function validated(data){if(data?.ownerKey!==ownerKey||data?.sessionKey!==sessionKey)throw Error('SESSION_CHANGED');if(!Array.isArray(data.reviews)||data.reviews.length>50)throw Error('UNAVAILABLE');const ids=new Set();for(const item of data.reviews){if(!uuid.test(item?.id)||!uuid.test(item?.itemId)||ids.has(item.id)||!clean(item.title,100)||!clean(item.displayName,40)||!['ai','member','owner_curated'].includes(item.label)||item.imageUrl!==base+'/reviews/'+item.id+'/image')throw Error('UNAVAILABLE');ids.add(item.id);}return data;}
async function context(run){return validated(await request('/reviews',{},run));}
function render(data){current=data;const renderRun=++renderEpoch,run=epoch;cards.clear();queue.replaceChildren();for(const item of data.reviews){const article=node('article'),image=node('img'),select=node('select'),card={item,article,image,select,buttons:[],loaded:false};cards.set(item.id,card);image.alt=item.title;select.setAttribute('aria-label','Decision reason for '+item.title);for(const reason of reasons){const option=node('option',reason.replaceAll('_',' '));option.value=reason;select.append(option);}select.value=reasons[0];article.append(node('h2',item.title),node('p',(item.label==='owner_curated'?'Presented by ':'Created by ')+item.displayName+' · '+({owner_curated:'Owner-curated artwork',ai:'AI-assisted',member:'Member artwork'}[item.label])),image,select);
 image.onload=async()=>{try{await image.decode();if(!active(run)||renderRun!==renderEpoch)return;const fresh=await context(run);if(!active(run)||renderRun!==renderEpoch)return;if(listKey(fresh)!==listKey(current)){render(fresh);status.textContent='The review queue changed. Inspect the current preview before deciding.';return;}current=fresh;card.loaded=true;allow();}catch(error){if(!active(run)||renderRun!==renderEpoch)return;if(error.message==='SESSION_CHANGED')invalidate('Your owner session changed or expired. Private previews were cleared. Sign in again, then reload to recover any saved decision.');else{card.loaded=false;status.textContent='Artwork could not be verified. Approval remains disabled.';allow();}}};
 image.onerror=()=>{if(active(run)&&renderRun===renderEpoch){card.loaded=false;status.textContent='Artwork unavailable. Approval remains disabled.';allow();}};
 for(const decision of ['approved','rejected']){const button=node('button',decision==='approved'?'Approve':'Reject');button.type='button';button.dataset.decision=decision;button.disabled=true;button.onclick=()=>{if(button.disabled||busy||locked||pending||!current)return;let requestId;try{requestId=crypto.randomUUID();}catch{status.textContent='A safe request ID could not be created. Nothing was sent.';return;}void send({ownerKey,sessionKey,payload:{requestId,reviewId:item.id,decision,reason:select.value}},false,itemKey(item));};card.buttons.push(button);article.append(button);}queue.append(article);image.src=item.imageUrl;}allow();}
async function load(){if(busy||locked)return;busy=true;allow();const run=epoch;try{const data=await context(run);if(!active(run))return;render(data);status.textContent=pending?'A saved decision needs recovery. Refreshing made no changes. Use Recover the same decision deliberately.':data.reviews.length?'Review each image and choose a reason.':'No pending submissions.';}catch(error){if(!active(run))return;if(error.message==='SESSION_CHANGED')invalidate('Your owner session changed or expired. Private previews were cleared. Sign in again, then reload to recover any saved decision.');else{current=null;renderEpoch++;cards.clear();queue.replaceChildren();status.textContent='Review queue unavailable. Refresh deliberately; any saved decision is retained.';}}finally{if(active(run)){busy=false;allow();}}}
async function send(attempt,recovering=false,expected=''){if(busy||locked||(!recovering&&pending)||!saved(attempt))return;const run=epoch;let sent=false;try{persist(attempt);}catch{invalidate('Receipt storage is unavailable. Nothing was sent. Restore session storage and reload before deciding.');return;}busy=true;allow();status.textContent=recovering?'Recovering the exact saved decision…':'Rechecking the current owner and review…';try{const fresh=await context(run);if(!active(run))return;if(!recovering&&itemKey(fresh.reviews.find(item=>item.id===attempt.payload.reviewId))!==expected){forget();render(fresh);status.textContent='This review changed or left the queue. Nothing was sent. Inspect the current preview before deciding.';return;}current=fresh;sent=true;const result=await request('/review/decide',{method:'POST',headers:{'Content-Type':'application/json','X-Lounge-CSRF':csrf},body:JSON.stringify(attempt.payload)},run);if(result?.ok!==true)throw Error('UNAVAILABLE');const refreshed=await context(run);if(!active(run))return;forget();render(refreshed);status.textContent=recovering?'The saved decision receipt is resolved. The current queue was refreshed; recovery does not assert that historical approval is still active.':'Decision recorded. The current review queue was refreshed. Keep the stage held until the attended reveal.';}catch(error){if(!active(run))return;if(error.message==='SESSION_CHANGED'){invalidate('Your owner session changed or expired. The saved decision receipt is retained. Sign in again, then reload and recover that same decision.');return;}if(error.message==='STORAGE'){invalidate('The receipt could not be cleared safely. Reload and recover the same saved decision.');return;}if(Object.hasOwn(commandTerminal,error.message)){try{forget();}catch{invalidate('Receipt storage needs attention. Reload and recover the same saved decision.');return;}current=null;cards.clear();queue.replaceChildren();status.textContent=commandTerminal[error.message];status.focus?.();return;}if(recovering||sent&&error.message!=='REFUSED'){status.textContent='Outcome unknown or recovery unavailable. The original receipt is retained. Use Recover the same decision; no new decision can start.';}else{try{forget();}catch{invalidate('Receipt storage needs attention. Reload and recover the same saved decision.');return;}current=null;cards.clear();queue.replaceChildren();status.textContent=sent?'Decision refused. Refresh the current queue before another decision.':'The owner session or review could not be rechecked. Nothing was sent. Refresh deliberately.';}}finally{if(active(run)){busy=false;allow();}}}
q('refresh').onclick=load;q('recover').onclick=()=>{if(!q('recover').disabled&&pending)void send(pending,true);};q('stop').onclick=()=>invalidate('Stopped. Private previews were cleared. Reload to continue; any saved decision is retained.');
window.addEventListener('pagehide',()=>invalidate('Private previews cleared. Reload to continue; any saved decision is retained.'),{once:true});window.addEventListener('pageshow',event=>{if(event.persisted)window.location.reload();});
try{if(!hash.test(ownerKey)||!hash.test(sessionKey))throw Error('INVALID_CONTEXT');const raw=sessionStorage.getItem(storageKey);if(raw!==null){if(raw.length>2048)throw Error('INVALID_RECEIPT');const value=JSON.parse(raw);if(value?.ownerKey!==ownerKey)throw Error('OTHER_OWNER');if(!saved(value))throw Error('INVALID_RECEIPT');pending=value;}}catch(error){invalidate(error.message==='OTHER_OWNER'?'A pending decision belongs to another owner context. Its private details are hidden. Recover with the original owner before starting another decision.':'Saved receipt storage or owner context is unavailable. No decision can start. Restore the session and reload; do not discard an unknown receipt.');}
allow();if(!locked)void load();
`;
